import { chmodSync, statSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { Recording } from "../../../src/session/recording";
import { writeSessionVersion } from "../../../src/session/protocol";

const dir = process.env.PACER_TEST_DIR;
const mask = process.env.PACER_TEST_UMASK;
if (!dir || !mask) throw Error("missing isolated test directory or umask");
process.umask(Number.parseInt(mask, 8));
chmodSync(dir, 0o777);
writeFileSync(join(dir, "session.version"), "old");
chmodSync(join(dir, "session.version"), 0o666);
writeSessionVersion(dir, null);
const recording = new Recording(dir);
for (const name of ["session.log", "session.ckpt"]) chmodSync(join(dir, name), 0o666);
writeFileSync(join(dir, "stdout"), "");
chmodSync(join(dir, "stdout"), 0o666);
await recording.output(Buffer.from("abc\n"));
recording.checkpoint();
await recording.close();
const mode = (name: string) => statSync(join(dir, name)).mode & 0o777;
console.log(JSON.stringify({ dir: statSync(dir).mode & 0o777, version: mode("session.version"), log: mode("session.log"), checkpoint: mode("session.ckpt"), stdout: mode("stdout") }));
